def _mkt_hiring(assignment, interview, screen_note):
    return [
        stage("Round 1 — Resume and portfolio screening", "Before any interview", screen_note,
              [paper("Resume with results (numbers) and tools", "PDF", "—", "Show outcomes: traffic, leads, sales, engagement"),
               paper("Portfolio / case studies / samples", "Links or PDF", "—", "2–4 strong pieces beat 15 weak ones")],
              "Relevant samples and clear results that match the job post."),
        stage("Round 2 — Assignment or case study", "Common for marketing roles", "A practical task to see how you think and execute.",
              [paper(assignment, "Take-home or live", "2 hours – 3 days", "Explain your reasoning, not just the output")],
              "Practical, well-reasoned work with measurable goals."),
        stage("Round 3 — Interview(s)", "1–3 rounds with the team and manager", "Tools, strategy, metrics and your past work.",
              [paper(interview, "Discussion", "30–60 min each", "Use real examples and numbers")],
              "Clear answers backed by data and examples from your projects."),
        stage("Round 4 — HR / founder round and offer", "Final", "Culture fit, expectations, notice period and salary.",
              [], "Be honest about your experience; read the offer letter carefully."),
    ]


def _extra(tools, day, projects, questions, earn):
    return [
        {"id": "tools", "nav": "Tools", "heading": "Tools you will use", "intro": "Learn the free versions first; most companies use similar tools.",
         "columns": ["Tool", "Used for", "Cost to start"], "rows": tools},
        {"id": "typical-day", "nav": "A typical day", "heading": "A typical day in this job", "items": day},
        {"id": "projects", "nav": "Portfolio projects", "heading": "Portfolio projects to build",
         "intro": "Build these on your own site, a friend's business or a mock brand. Write each one as a short case study: goal → what you did → result.",
         "columns": ["Project", "What it proves"], "rows": projects},
        {"id": "interview-questions", "nav": "Interview questions", "heading": "Interview questions to practise", "items": questions},
        {"id": "ways-to-earn", "nav": "Ways to earn", "heading": "Ways to work and earn", "columns": ["Path", "How it works", "Good for"], "rows": earn},
    ]


